import{d as g,C as t,o as h,c as d,j as i,a as e,E as a,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第10章","description":"《中庸》第 10 章——子路问强。南方的含忍、北方的果敢之外，孔子给出君子之强：和而不流、中立而不倚、始终不变。","frontmatter":{"title":"中庸·第10章","description":"《中庸》第 10 章——子路问强。南方的含忍、北方的果敢之外，孔子给出君子之强：和而不流、中立而不倚、始终不变。","category":"guide","aliases":["第10章","中庸第10章","子路问强"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-10.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-10.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-10.md"},f=g({...m,setup(p){const o=[{id:"sanqiang",label:"南方之强 · 北方之强 · 抑而强与",showLabel:!0,sentences:[["子路问强。子曰：“南方之强",{text:"与",glossary:"yu"},"？北方之强与？",{text:"抑",glossary:"yi"},{text:"而",glossary:"er"},"强与？宽柔以教，不报无道，南方之强也，君子居之。",{text:"衽金革",glossary:"renjinge"},"，死而不厌，北方之强也，而强者居之。"]],note:"子路问什么是「强」。孔子先反问：是南方之强、北方之强，还是你自己的强？接着说南方之强：「宽柔以教，不报无道」——以宽厚柔和教人，不报复无道之人，这是君子所居之强；北方之强：「衽金革，死而不厌」——枕着兵器甲胄、至死不怕死，这是勇武之人所居之强。"},{id:"hebutliu",label:"和而不流 · 中立而不倚",showLabel:!0,sentences:[["故君子",{text:"和而不流",glossary:"hebutliu"},"，强哉矫！",{text:"中立而不倚",glossary:"zhonglibuyi"},"，强哉矫！"]],note:"那么君子之强如何？「和而不流」——和顺而不随波逐流；「中立而不倚」——守中而不偏倚。每句之后都以「强哉矫！」（矫＝强盛之貌）赞叹。"},{id:"bubian",label:"国有道不变塞 · 国无道至死不变",showLabel:!0,sentences:[["国有道，不变",{text:"塞",glossary:"se"},"焉，强哉矫！国无道，至死不变，强哉矫！”"]],note:"再进一层：「国有道，不变塞焉」——国家有道时，不改变困穷时的操守；「国无道，至死不变」——国家无道时，至死也不变节。四者合观，才是君子之强。"}],l=[{id:"zilu",term:"子路",pinyin:"zǐ lù",meaning:"孔子弟子仲由，字子路，好勇。朱注以舜（知）、颜渊（仁）、子路（勇）分属三达德，此章正举「勇」。"},{id:"yu",term:"与",pinyin:"yú",meaning:"同「欤」，疑问语气词。读 yú。"},{id:"yi",term:"抑",pinyin:"yì",meaning:"语辞，表选择：还是、或者。"},{id:"er",term:"而",pinyin:"ěr",meaning:"汝、你。「抑而强与」即「还是你所认为的强呢」。"},{id:"renjinge",term:"衽金革",pinyin:"rèn jīn gé",meaning:"衽：卧席；金：戈兵之属；革：甲胄之属。枕戈披甲，即勇于赴战。"},{id:"hebutliu",term:"和而不流",pinyin:"hé ér bù liú",meaning:"和顺而不随波逐流。朱注谓四句皆「汝之所当强也」。"},{id:"zhonglibuyi",term:"中立而不倚",pinyin:"zhōng lì ér bù yǐ",meaning:"守中而立、不偏倚。倚：偏着。"},{id:"se",term:"塞",pinyin:"sè",meaning:"未达、未显达。朱注：「国有道，不变未达之所守；国无道，不变平生之所守也。」"}];return(y,n)=>{const s=t("DaoTextReading"),r=t("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第10章",tabindex:"-1"},[e("中庸·第10章 "),i("a",{class:"header-anchor",href:"#中庸·第10章","aria-label":'Permalink to "中庸·第10章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第十章由子路问强引出。孔子先划开两种「强」——南方之强是"),i("strong",null,"含忍"),e("，北方之强是"),i("strong",null,"果敢"),e("——然后给出君子之强："),i("strong",null,"和而不流、中立而不倚"),e("，以及无论世道如何都不改变。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(s,{colophon:"南方之强 · 北方之强 · 君子之强",tone:"ink",sections:o,glossary:l,"default-mode":"slips","aria-label":"中庸·第10章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(r,{items:[{term:"与",pinyin:["yú"],meaning:"同「欤」，疑问语气词。"},{term:"抑",pinyin:["yì"],meaning:"语辞，表选择：还是。"},{term:"而",pinyin:["ěr"],meaning:"汝、你。「抑而强与」即「还是你所认为的强呢」。"},{term:"衽金革",pinyin:["rèn","jīn","gé"],meaning:"衽：卧席；金：戈兵；革：甲胄。枕戈披甲，勇于赴战。"},{term:"和而不流",pinyin:["hé","ér","bù","liú"],meaning:"和顺而不随波逐流。"},{term:"中立而不倚",pinyin:["zhōng","lì","ér","bù","yǐ"],meaning:"守中而立、不偏倚。倚：偏着。"},{term:"塞",pinyin:["sè"],meaning:"未达、未显达。不变塞，即不改变未达时所守。"}]}),a(r,{items:[{term:"强哉矫",pinyin:["qiáng","zāi","jiǎo"],meaning:"多么刚强啊！矫：强貌。《诗》「矫矫虎臣」即此义。四句连用，是孔子对君子之强的赞叹。"},{term:"自胜其人欲之私",pinyin:["zì","shèng","qí","rén","yù","zhī","sī"],meaning:"朱注解此章云：此四者「非有以自胜其人欲之私，不能择而守也」——正与第 9 章「中庸不可能」相呼应。"}]}),n[4]||(n[4]=u("",24))])}}});export{c as __pageData,f as default};
